            }
            return m0; // spaced plain word — the #N stays a local ref
        });
    var m = /(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?)\s+#(\d+)/i.exec(text);
    if (m) return parseInt(m[1], 10);
    m = /(^|[^0-9])#(\d+)([^0-9]|$)/.exec(text);
    return m ? parseInt(m[2], 10) : null;
}

