    // keywords ('Closes #123') intact — and the keyword check below is
    // belt-and-suspenders for 'closes repo#N'.
    text = text.replace(/(^|[^A-Za-z0-9_.\-/])([A-Za-z0-9_.-]+(?:\/[A-Za-z0-9_.-]+)?)([ \t]*)(#\d+)/g,
