        var wave = srcMod.query(Object.assign({}, RULE, { limit: 10 }),
            { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
        assert.deepEqual(wave.map(function (i) { return i.key; }), ['pr-1305', 'pr-1314'],
