            1305: { number: 1305, state: 'OPEN', checks: 'green', mergeState: 'BLOCKED', mergeable: false },
            1314: { number: 1314, state: 'OPEN', checks: 'green', mergeState: 'BLOCKED', mergeable: false }
        });
        var fresh = srcMod.query({
            source: 'github',
