            id: 'validate-fresh'
        }, { repoInfo: { owner: 'IstiN', repo: 'flutter_agent_harness' } });
        assert.equal(fresh.length, 0,
            'validate-fresh is blind to the masked-green head — this IS the gh-759 dead zone');
    });
});

