            draft: false, user: { login: author || 'ai-teammate' },
            head: { ref: 'ai/gh-' + (n - 1) }, body: 'Closes #' + (n - 1)
        };
    }

    test('matches exactly the un-armed, un-approved, BLOCKED masked-green PRs (multi-item wave)', function () {
        var srcMod = load({
