            }
            console.log('  ▶ ' + key + ' park cleared (fresh human push) — validation proceeds');
        } else {
            console.log('  ⏭️  ' + key + ' validation_failed — parked; NO validation CI' +
                        ' until a HUMAN push newer than the park clears it');
