// ZERO labels rotted for hours (live #826-class). The CLEAN exclusion now
// stands only while the latch is absent: green + CLEAN + zero lifecycle
// labels + the issue's ai_developed latch (the dev leg's done-marker —
// machine-work gating, guests stay unarmed) arms validation exactly like
// the BLOCKED branch; without the latch the old exclusion applies
// (merge-validated owns CLEAN). States not listed in the latch are inert
// — BEHIND/DIRTY stay excluded via notMergeState. Fetch failures fail
// CLOSED (no latch → excluded), and the per-tick TTL cache keeps the
// per-rule re-query cheap.
if (q.mergeStateLatch) {
    var latchState = item.pr ? item.pr.mergeState : null;
    var latchWant = latchState ? q.mergeStateLatch[latchState] : null;
    if (latchWant) {
        var latchIssue = item.issueNumber ? cachedIssueLabels(repoInfo, item.issueNumber) : null;
        if (!latchIssue) return false;
        for (var li = 0; li < latchWant.length; li++) {
            if (latchIssue.indexOf(latchWant[li]) === -1) return false;
        }
    }
```

